import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./Home.css"; // Using same CSS file for consistency

const Emergency = () => {
  const navigate = useNavigate();

  // Local state with emergency contacts
  const [contacts, setContacts] = useState([
    { name: "Police", number: "100" },
    { name: "Fire", number: "101" },
    { name: "Ambulance", number: "102" },
    { name: "Women Helpline", number: "1091" },
    { name: "Disaster Management", number: "108" },
  ]);

  const handleGoHome = () => {
    navigate("/");
  };

  return (
    <div className="home-container">
      <h1 className="home-title">Emergency Contacts</h1>

      <ul className="contacts-list">
        {contacts.map((contact, index) => (
          <li key={index} className="contact-item">
            <span className="contact-name">{contact.name}</span> :{" "}
            <span className="contact-number">{contact.number}</span>
          </li>
        ))}
      </ul>

      <button onClick={handleGoHome} className="btn">
        Back to Home
      </button>
    </div>
  );
};

export default Emergency;
